  const routes = [...new Set(incidents.map(i => i.route))].sort();
  const filtered = useMemo(() => incidents.filter(i => (scope === 'all' || !terminal(i.status)) && (scope !== 'mine' || i.owner?.id === actor?.id) && (scope !== 'unassigned' || !i.owner) && (route === 'all' || i.route === route) && [i.title, i.number, i.route, i.jurisdiction].some(s => s.toLowerCase().includes(search.toLowerCase()))).sort((a, b) => ['critical', 'major', 'moderate', 'minor'].indexOf(a.severity) - ['critical', 'major', 'moderate', 'minor'].indexOf(b.severity)), [incidents, scope, route, search, actor?.id]);
