    {(training || runtime?.mode === 'training') && <div className="training-banner"><span><ShieldCheck size={14} /><strong>{runtime?.beta ? 'BETA · PRIVATE TRAINING WORKSPACE' : 'TRAINING WORKSPACE'}</strong> Synthetic incidents and {runtime?.beta ? 'simulated' : 'local SNMP'} sign emulators. No physical commands are sent.{runtime?.beta ? ' Not for operational use.' : ''}</span>{runtime?.beta && <><button disabled={busy} onClick={() => leaveBeta(true)}>Delete my workspace</button><button disabled={busy} onClick={() => leaveBeta(false)}>Sign out</button></>}<button onClick={() => open('help')}>How this workspace works <ArrowRight size={12} /></button></div>}
